  let mHex = m.toString(16);
  if (mHex.length % 2 !== 0) mHex = '0' + mHex;
  const mBuf = Buffer.alloc(k);
  const raw = Buffer.from(mHex, 'hex');
  raw.copy(mBuf, k - raw.length);

