  const inner = node.kids.map((k) => (k.__el ? render(k, depth + 1) : `${pad}  ${escapeXml(k)}`)).join('\n');
  return `${pad}<${node.name}${attrs}>\n${inner}\n${pad}</${node.name}>`;
